static unsigned int wifiscan_freq_to_channel(unsigned int freq)
{
  if (freq >= 2412 && freq <= 2472)
    {
      return (freq - 2407) / 5;
    }

  if (freq == 2484)
    {
      return 14;
    }

  if (freq >= 5000 && freq <= 5900)
    {
      return (freq - 5000) / 5;
    }

  return freq;
}

