static int aic_wifi_scan_append_channels(struct scanu_start_req *req,
                                         const struct mac_chan_def *chans,
                                         unsigned int chan_cnt)
{
	unsigned int i;

	for(i = 0; (i < chan_cnt) && (req->chan_cnt < SCAN_CHANNEL_MAX); i++)
	{
		if(chans[i].flags & CHAN_DISABLED)
			continue;

		req->chan[req->chan_cnt++] = chans[i];
	}

	return req->chan_cnt;
}

int aic_wifi_scan_direct_start(void)
{
	struct fhost_cntrl_link *link;
	struct fhost_vif_status status;
	struct scanu_start_req req;
	int ret;

	if(!wifi_dev.g_wifi_init || g_rwnx_hw == NULL)
	{
		AIC_LOG_PRINTF("aic_wifi_scan_direct_start: WiFi is not initialized");
		return -ENODEV;
	}

	link = fhost_cntrl_cfgrwnx_link_open();
	if(link == NULL)
	{
		AIC_LOG_PRINTF("aic_wifi_scan_direct_start: open control link failed");
		return -EIO;
	}

	memset(&status, 0, sizeof(status));
	ret = fhost_get_vif_status(0, &status);
	if((ret < 0) || (status.type != VIF_STA))
	{
		ret = fhost_set_vif_type(link, 0, VIF_STA, false);
		if(ret < 0)
		{
			AIC_LOG_PRINTF("aic_wifi_scan_direct_start: set STA vif failed %d", ret);
			fhost_cntrl_cfgrwnx_link_close(link);
			return ret;
		}
	}

	fhost_cntrl_cfgrwnx_link_close(link);

	memset(&req, 0, sizeof(req));
	req.vif_idx = 0;
	memset(&req.bssid, 0xff, sizeof(req.bssid));
	req.ssid_cnt = 1;
	req.ssid[0].length = 0;
	req.duration = 30000;
	aic_wifi_scan_append_channels(&req, fhost_chan.chan2G4,
	                              fhost_chan.chan2G4_cnt);
	aic_wifi_scan_append_channels(&req, fhost_chan.chan5G,
	                              fhost_chan.chan5G_cnt);
	if(req.chan_cnt == 0)
	{
		AIC_LOG_PRINTF("aic_wifi_scan_direct_start: no available channel");
		return -ENODATA;
	}

	fhost_scan_start();
	ret = rwnx_send_scanu_req(g_rwnx_hw, &req);
	AIC_LOG_PRINTF("aic_wifi_scan_direct_start: ret=%d chan_cnt=%u ssid_cnt=%u duration=%u",
	               ret, req.chan_cnt, req.ssid_cnt, req.duration);
	return ret;
}

