static int wifiscan_worker(void *arg)
{
  const struct wifiscan_args *args = (const struct wifiscan_args *)arg;
  wifi_ap_list_t ap_list;
  int i;

  memset(&ap_list, 0, sizeof(ap_list));

  if (args->scan_link)
